// Normalize telemetry output to ThingsBoard flat JSON format
// Input: msg.payload = {key1: val1, key2: val2, ...}
// Input: msg.timestamp (optional, epoch_ms)
// Output: msg.payload = {"ts": <epoch_ms>, "values": {key1: val1, ...}}

const values = {};
const raw = msg.payload;

if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    node.error('[protocol-normalization] InvalidPayload: expected object, got ' + typeof raw, msg);
    return null;
}

for (const [key, val] of Object.entries(raw)) {
    // Validate key format: snake_case (at least one underscore)
    if (!/^[a-z][a-z0-9]*(_[a-z0-9]+)+$/.test(key)) {
        node.warn('[protocol-normalization] InvalidKey: "' + key + '" does not match snake_case_unit pattern, skipping');
        continue;
    }

    // Coerce string numbers to float
    if (typeof val === 'string') {
        const num = parseFloat(val);
        if (!isNaN(num)) {
            values[key] = num;
        } else {
            values[key] = val;
        }
    } else if (typeof val === 'number' && isFinite(val)) {
        values[key] = val;
    } else if (typeof val === 'boolean') {
        values[key] = val;
    } else {
        node.warn('[protocol-normalization] InvalidValue: key "' + key + '" has unsupported type, skipping');
        continue;
    }
}

if (Object.keys(values).length === 0) {
    node.error('[protocol-normalization] EmptyPayload: no valid telemetry keys after normalization', msg);
    return null;
}

const ts = msg.timestamp || Date.now();

msg.payload = {
    ts: ts,
    values: values
};

// Set output topic if provided
if (msg.output_topic) {
    msg.topic = msg.output_topic;
}

return msg;

info:
Protocol Normalization Flow

Purpose: Normalize diverse sensor protocol data into unified ThingsBoard telemetry format.

Supported Protocols:

1. Direct Polling (Node-RED polls device, disabled by default):
   - Modbus TCP: modbus-read node polls holding registers via TCP
   - Modbus RTU: modbus-read node polls holding registers via RS-485 serial
   - OPC-UA: OpcUa-Client node subscribes to data changes
   - BACnet: bacnet-read node polls analog inputs/values via BACnet/IP

2. Bridge-based (external gateway publishes to Mosquitto):
   - LoRaWAN: ChirpStack or similar publishes to nexus/raw/lorawan/{zone_id}/{device_id}
   - Zigbee: Zigbee2MQTT or similar publishes to nexus/raw/zigbee/{zone_id}/{device_id}
   - Z-Wave: Z-Wave bridge publishes to nexus/raw/zwave/{zone_id}/{device_id}
   - LwM2M: Leshan or similar publishes to nexus/raw/lwm2m/{zone_id}/{device_id}
   - SNMP: snmp2mqtt or similar publishes to nexus/raw/snmp/{zone_id}/{device_id}

Input:
- Raw MQTT: nexus/raw/{protocol}/{zone_id}/{device_id}
- Modbus TCP/RTU: direct register polling via modbus-read nodes
- OPC-UA: subscription data changes via OpcUa-Client node
- BACnet: property reads via bacnet-read node

Output:
- Normalized MQTT: nexus/{zone_id}/{device_id}/telemetry
- Format: {"ts": <epoch_ms>, "values": {"key": value}}

Telemetry key convention: snake_case with unit suffix
- vibration_mm_s, temperature_c, power_draw_kw

Error handling: catch node logs all errors in format:
[protocol-normalization] {error_type}: {message}

func:
// Extract protocol, zone_id, device_id from raw topic
// Topic format: nexus/raw/{protocol}/{zone_id}/{device_id}

const parts = msg.topic.split('/');

if (parts.length !== 5 || parts[0] !== 'nexus' || parts[1] !== 'raw') {
    node.error('[protocol-normalization] InvalidTopic: expected nexus/raw/{protocol}/{zone_id}/{device_id}, got ' + msg.topic, msg);
    return null;
}

msg.protocol = parts[2];
msg.zone_id = parts[3];
msg.device_id = parts[4];
msg.output_topic = 'nexus/' + msg.zone_id + '/' + msg.device_id + '/telemetry';

return msg;

// Parse raw payload and map to standardized telemetry keys
// Supports JSON payloads with arbitrary keys
// Uses configurable key mapping from flow context

// Default key mappings: raw_key -> standard_key
// Can be overridden via flow context 'keyMappings'
const defaultMappings = {
    "_default": {
        "vibration": "vibration_mm_s",
        "vib": "vibration_mm_s",
        "temperature": "temperature_c",
        "temp": "temperature_c",
        "power": "power_draw_kw",
        "power_draw": "power_draw_kw",
        "vibration_mm_s": "vibration_mm_s",
        "temperature_c": "temperature_c",
        "power_draw_kw": "power_draw_kw"
    },
    "lwm2m": {
        "3303/0/5700": "temperature_c",
        "3313/0/5702": "vibration_mm_s",
        "3328/0/5700": "power_draw_kw",
        "temperature": "temperature_c",
        "vibration": "vibration_mm_s",
        "power": "power_draw_kw"
    },
    "snmp": {
        "1.3.6.1.4.1.99.1.1": "temperature_c",
        "1.3.6.1.4.1.99.1.2": "vibration_mm_s",
        "1.3.6.1.4.1.99.1.3": "power_draw_kw",
        "temperature": "temperature_c",
        "vibration": "vibration_mm_s",
        "power": "power_draw_kw"
    }
};

const userMappings = flow.get('keyMappings') || {};
const keyMappings = Object.assign({}, defaultMappings, userMappings);
const protocol = msg.protocol || '_default';

// Parse payload: try JSON first, then CSV, then reject binary
let raw;
if (typeof msg.payload === 'object' && msg.payload !== null && !Buffer.isBuffer(msg.payload)) {
    raw = msg.payload;
} else if (Buffer.isBuffer(msg.payload)) {
    // Binary payload: attempt to decode as UTF-8 string first
    const str = msg.payload.toString('utf8').trim();
    try {
        raw = JSON.parse(str);
    } catch (e) {
        // Try CSV: key1:val1,key2:val2
        if (str.includes(',') && str.includes(':')) {
            raw = {};
            const parts = str.split(',');
            for (const part of parts) {
                const kv = part.trim().split(':');
                if (kv.length === 2) {
                    raw[kv[0].trim()] = kv[1].trim();
                }
            }
            if (Object.keys(raw).length === 0) {
                node.error('[protocol-normalization] BinaryParseError: buffer has no valid key:value pairs in CSV format', msg);
                return null;
            }
        } else {
            node.error('[protocol-normalization] BinaryParseError: buffer is not valid JSON or CSV', msg);
            return null;
        }
    }
} else if (typeof msg.payload === 'string') {
    const trimmed = msg.payload.trim();
    try {
        raw = JSON.parse(trimmed);
    } catch (e) {
        // Try CSV: key1:val1,key2:val2
        if (trimmed.includes(',') && trimmed.includes(':')) {
            raw = {};
            const parts = trimmed.split(',');
            for (const part of parts) {
                const kv = part.trim().split(':');
                if (kv.length === 2) {
                    raw[kv[0].trim()] = kv[1].trim();
                }
            }
            if (Object.keys(raw).length === 0) {
                node.error('[protocol-normalization] CSVParseError: no valid key:value pairs found', msg);
                return null;
            }
        } else {
            node.error('[protocol-normalization] ParseError: payload is not valid JSON or CSV (key:val,key:val)', msg);
            return null;
        }
    }
} else {
    node.error('[protocol-normalization] InvalidPayload: unsupported payload type ' + typeof msg.payload, msg);
    return null;
}

if (typeof raw !== 'object' || raw === null) {
    node.error('[protocol-normalization] InvalidPayload: expected object after parse', msg);
    return null;
}

// Extract timestamp if present in raw data
const timestamp = raw.ts || raw.timestamp || Date.now();

// Get mapping for this protocol, fallback to _default
const mapping = keyMappings[protocol] || keyMappings['_default'] || {};

// Map keys
const normalized = {};
for (const [rawKey, rawVal] of Object.entries(raw)) {
    if (rawKey === 'ts' || rawKey === 'timestamp') continue;
    const mappedKey = mapping[rawKey];
    if (!mappedKey) {
        node.warn('[protocol-normalization] UnmappedKey: "' + rawKey + '" has no mapping for protocol "' + protocol + '", skipping');
        continue;
    }
    normalized[mappedKey] = rawVal;
}

msg.payload = normalized;
msg.timestamp = timestamp;

return msg;

// Map Modbus register values to telemetry keys
// msg.payload = array of register values from modbus-read

// Register mapping: index -> {key, scale, offset}
// Can be overridden via flow context 'modbusRegisterMap'
const defaultRegisterMap = {
    0: { key: "vibration_mm_s", scale: 0.01, offset: 0 },
    1: { key: "temperature_c", scale: 0.1, offset: -40 },
    2: { key: "power_draw_kw", scale: 0.001, offset: 0 }
};

const registerMap = flow.get('modbusRegisterMap') || defaultRegisterMap;
const zone_id = env.get('ZONE_ID') || 'zone-01';
const device_id = env.get('DEVICE_ID') || 'modbus-001';

if (!Array.isArray(msg.payload)) {
    node.error('[protocol-normalization] ModbusError: expected array payload, got ' + typeof msg.payload, msg);
    return null;
}

const normalized = {};
for (const [index, config] of Object.entries(registerMap)) {
    const i = parseInt(index);
    if (i < msg.payload.length) {
        const rawValue = msg.payload[i];
        if (typeof rawValue === 'number' && isFinite(rawValue)) {
            normalized[config.key] = parseFloat(((rawValue * config.scale) + config.offset).toFixed(6));
        }
    }
}

if (Object.keys(normalized).length === 0) {
    node.error('[protocol-normalization] ModbusEmpty: no registers mapped from ' + msg.payload.length + ' values', msg);
    return null;
}

msg.payload = normalized;
msg.timestamp = Date.now();
msg.output_topic = 'nexus/' + zone_id + '/' + device_id + '/telemetry';

return msg;

// Map OPC-UA subscription data to standardized telemetry keys
// OPC-UA Client subscribe output: msg.payload contains the data value
// msg.topic contains the OPC-UA node ID (e.g., ns=3;s=Temperature)

// Node ID mapping: OPC-UA nodeId -> {key, scale, offset}
// Can be overridden via flow context 'opcuaNodeMap'
const defaultNodeMap = {
    "ns=3;s=Temperature": { key: "temperature_c", scale: 1, offset: 0 },
    "ns=3;s=Vibration": { key: "vibration_mm_s", scale: 1, offset: 0 },
    "ns=3;s=Power": { key: "power_draw_kw", scale: 0.001, offset: 0 }
};

const nodeMap = flow.get('opcuaNodeMap') || defaultNodeMap;
const zone_id = env.get('ZONE_ID') || 'zone-01';
const device_id = env.get('OPCUA_DEVICE_ID') || env.get('DEVICE_ID') || 'opcua-001';

const nodeId = msg.topic || '';
const mapping = nodeMap[nodeId];

if (!mapping) {
    node.warn('[protocol-normalization] OpcUaUnmappedNode: "' + nodeId + '" has no mapping, skipping');
    return null;
}

let value = msg.payload;
if (typeof value === 'object' && value !== null && value.value !== undefined) {
    value = value.value;
}

if (typeof value !== 'number' || !isFinite(value)) {
    node.error('[protocol-normalization] OpcUaValueError: non-numeric value for node "' + nodeId + '"', msg);
    return null;
}

const scaled = parseFloat(((value * mapping.scale) + mapping.offset).toFixed(6));

msg.payload = {};
msg.payload[mapping.key] = scaled;
msg.timestamp = Date.now();
msg.output_topic = 'nexus/' + zone_id + '/' + device_id + '/telemetry';

return msg;

// Map BACnet property values to standardized telemetry keys
// bacnet-read output: msg.payload contains BACnet read result
// msg.payload.values[0].value contains the actual value

// Object mapping: "objectType:instance" -> {key, scale, offset}
// Can be overridden via flow context 'bacnetObjectMap'
const defaultObjectMap = {
    "analog-input:0": { key: "temperature_c", scale: 1, offset: 0 },
    "analog-input:1": { key: "vibration_mm_s", scale: 1, offset: 0 },
    "analog-value:0": { key: "power_draw_kw", scale: 1, offset: 0 }
};

const objectMap = flow.get('bacnetObjectMap') || defaultObjectMap;
const zone_id = env.get('ZONE_ID') || 'zone-01';
const device_id = env.get('BACNET_DEVICE_ID') || env.get('DEVICE_ID') || 'bacnet-001';

const normalized = {};

// Handle BACnet read response format
if (msg.payload && msg.payload.values && Array.isArray(msg.payload.values)) {
    for (const val of msg.payload.values) {
        const objType = val.objectId ? val.objectId.type : 'analog-input';
        const objInst = val.objectId ? val.objectId.instance : 0;
        const lookupKey = objType + ':' + objInst;
        const mapping = objectMap[lookupKey];
        if (mapping && typeof val.value === 'number' && isFinite(val.value)) {
            normalized[mapping.key] = parseFloat(((val.value * mapping.scale) + mapping.offset).toFixed(6));
        }
    }
} else if (typeof msg.payload === 'object' && msg.payload !== null) {
    // Simple object format fallback
    for (const [key, val] of Object.entries(msg.payload)) {
        const mapping = objectMap[key];
        if (mapping && typeof val === 'number' && isFinite(val)) {
            normalized[mapping.key] = parseFloat(((val * mapping.scale) + mapping.offset).toFixed(6));
        }
    }
}

if (Object.keys(normalized).length === 0) {
    node.error('[protocol-normalization] BACnetEmpty: no properties mapped from payload', msg);
    return null;
}

msg.payload = normalized;
msg.timestamp = Date.now();
msg.output_topic = 'nexus/' + zone_id + '/' + device_id + '/telemetry';

return msg;

// Format error message for logging
const errorSource = msg.error ? msg.error.source : {};
const errorMsg = msg.error ? msg.error.message : 'Unknown error';
const nodeName = errorSource.name || errorSource.id || 'unknown';

node.warn('[protocol-normalization] ' + nodeName + ': ' + errorMsg);

// Prepare error status for gateway health (consumed by gateway-health flow in Story 1.6)
msg.payload = {
    ts: Date.now(),
    values: {
        norm_error_count: 1,
        norm_last_error: errorMsg.substring(0, 200)
    }
};
msg.topic = 'nexus/internal/normalization-errors';

return msg;

// Load RBE deadband thresholds from environment variables into flow context
// Called once on deploy via inject node

var thresholds = {};

// Read per-key deadband thresholds from env vars
var tempDb = parseFloat(env.get('RBE_DEADBAND_TEMPERATURE_C'));
if (!isNaN(tempDb) && tempDb >= 0) {
    thresholds['temperature_c'] = tempDb;
}

var vibDb = parseFloat(env.get('RBE_DEADBAND_VIBRATION_MM_S'));
if (!isNaN(vibDb) && vibDb >= 0) {
    thresholds['vibration_mm_s'] = vibDb;
}

var powerDb = parseFloat(env.get('RBE_DEADBAND_POWER_DRAW_KW'));
if (!isNaN(powerDb) && powerDb >= 0) {
    thresholds['power_draw_kw'] = powerDb;
}

// Default deadband for unconfigured keys
var defaultDb = parseFloat(env.get('RBE_DEADBAND_DEFAULT'));
if (isNaN(defaultDb) || defaultDb < 0) {
    defaultDb = 0;
}

global.set('rbeThresholds', thresholds);
global.set('rbeDefaultDeadband', defaultDb);
global.set('rbeFilteredCount', 0);

var keyCount = Object.keys(thresholds).length;
node.status({fill: 'green', shape: 'dot', text: keyCount + ' keys configured, default=' + defaultDb});
node.warn('[rbe-filter] Config loaded: ' + keyCount + ' per-key thresholds, default deadband=' + defaultDb);

return null;

// Read RBE filtered count from flow context and publish stats
// Resets count after publishing (per-interval count)

var filteredCount = global.get('rbeFilteredCount') || 0;

msg.payload = JSON.stringify({
    filtered_count: filteredCount,
    timestamp: Date.now()
});
msg.topic = 'nexus/internal/rbe-status';

// Reset count for next interval
global.set('rbeFilteredCount', 0);

node.status({fill: 'blue', shape: 'dot', text: 'filtered: ' + filteredCount});

return msg;
